    return BBL_CLOUD_PROVIDER;
}


bool GUI_App::check_login(const std::string& provider/* = ORCA_CLOUD_PROVIDER*/)
{
    bool result = false;
    if (m_agent) {
        result = m_agent->is_user_login(provider);
    }

    if (!result) {
        ShowUserLogin(true, provider);
    }
    return result;
}

