3	// Provider credential setup for the Agent dock.
4	//
5	// Verifying a key and building the service that will use it are the same act
6	// here: the check runs one real request through the provider adapter the
7	// Agent goes on to use, so a key that passes is a key the Agent is already
8	// talking through, and the round-trip the user is shown is the one that
9	// actually happened. Nothing separate has to be kept in sync with it.
10	//
11	// GUI-free and poll-driven, mirroring IAgentService: transport callbacks only
12	// queue work, and the owner releases outcomes from poll() on the GUI thread.
13	// Persistence is injected, so this file never reaches the keychain or
14	// AppConfig and stays linkable into the GUI-free contract tests.
15	
16	#include "AgentService.hpp"
17	#include "OpenAIResponsesAgent.hpp"
18	
19	#include <chrono>
20	#include <functional>
21	#include <memory>
22	#include <optional>
23	#include <string>
24	
25	namespace Slic3r::GUI::JusPrin::Agent {
26	
27	struct SetupCredentials
28	{
29	    std::string provider; // "openai"
30	    std::string api_key;
31	    std::string model;    // optional; empty keeps the adapter's default
32	    std::string endpoint; // optional; empty keeps the adapter's default
33	};
34	
35	struct SetupOutcome
36	{
37	    bool            ok{false};
38	    AgentError      error;      // set when !ok
39	    int             elapsed_ms{0};
40	    AgentServicePtr service;    // set when ok: verified, idle, ready to install
41	};
42	
43	class IAgentSetupService
44	{
45	public:
46	    virtual ~IAgentSetupService() = default;
47	
48	    virtual bool busy() const = 0;
49	
50	    // Begins one verification. False when a check is already running, the
51	    // credentials are incomplete, or this build has no adapter for the
52	    // provider.
53	    virtual bool start_check(const SetupCredentials& credentials) = 0;
54	    virtual void cancel() = 0;
55	
56	    // Releases at most one finished outcome; called from the owner's tick.
57	    virtual std::optional<SetupOutcome> poll() = 0;
58	
59	    // Persists credentials that have just been verified. Reports failure
60	    // rather than pretending: a key the keychain refused is a key the user
61	    // will have to enter again next launch, and they are told so.
62	    virtual bool commit(const SetupCredentials& credentials) = 0;
63	};
64	
65	using AgentSetupServicePtr = std::shared_ptr<IAgentSetupService>;
66	
67	// Providers this build can verify. The page offers the same list; the host
68	// checks anyway, so a page/host mismatch fails visibly instead of hanging.
69	bool setup_provider_supported(const std::string& provider);
70	
71	class ProviderKeySetup final : public IAgentSetupService
72	{
73	public:
74	    using TransportFactory = std::function<std::unique_ptr<IAgentHttpTransport>()>;
75	    using CommitFn         = std::function<bool(const SetupCredentials&)>;
76	    using Clock            = std::function<std::chrono::steady_clock::time_point()>;
77	
78	    // endpoint_override redirects the check the way JUSPRIN_OPENAI_ENDPOINT
79	    // redirects the live Agent, so a developer or a harness can point setup
80	    // at a stand-in instead of the real provider.
81	    ProviderKeySetup(TransportFactory transport,
82	                     CommitFn         commit,
83	                     std::string      endpoint_override = {},
84	                     Clock            clock             = {});
85	    ~ProviderKeySetup() override;
86	
87	    bool                        busy() const override { return m_candidate != nullptr; }
88	    bool                        start_check(const SetupCredentials& credentials) override;
89	    void                        cancel() override;
90	    std::optional<SetupOutcome> poll() override;
91	    bool                        commit(const SetupCredentials& credentials) override;
92	
93	private:
94	    int          elapsed_ms() const;
95	    SetupOutcome finish_ok();
96	
97	    TransportFactory                      m_transport_factory;
98	    CommitFn                              m_commit;
99	    std::string                           m_endpoint_override;
100	    Clock                                 m_clock;
101	    AgentServicePtr                       m_candidate;
102	    std::chrono::steady_clock::time_point m_started{};
103	};
